const CONFIG = {
  TEST_EMAIL: 'amanzrx4@gmail.com',
  PAYOUT_THRESHOLD: 1000,
  PAYOUT_DELAY_DAYS: 45,
  MODEL: 'deepseek-chat',
};

const SYSTEM_PROMPT = `You write royalty summary emails to authors on behalf of BookLeaf Publishing's royalty team.

## COMPANY OVERVIEW
BookLeaf Publishing is a self-publishing company operating in India and the US. It handles cover design, typesetting, ISBN assignment, printing, distribution and royalty management for authors. Packages: Standard Free (no upfront cost) and Bestseller Breakthrough (premium, with marketing and distribution add-ons). Printing is mainly at BookLeaf's in-house facility in Delhi, with print partners Repro India and Epitome Books.

## ROYALTY POLICY
- 80/20 split: 80% of the net profit per book goes to the author, 20% to BookLeaf.
- Net profit = MRP minus printing cost, platform commission (Amazon/Flipkart) and shipping charges.
- Royalties are calculated quarterly and paid within 45 days of the quarter ending.
- Minimum payout threshold: ₹ 1,000. If accumulated royalties are below this, they roll over to the next quarter.
- Payouts are made by bank transfer to the account linked in the author's dashboard.
- Authors can see a detailed royalty breakdown, with sales per platform, in their dashboard.
- Total earned = royalty paid + royalty pending.

## PRODUCTION STAGES
Manuscript Received, Editing (if opted), Cover Design, Typesetting, Proofreading, ISBN Assignment, Printing, Distribution Setup, Published & Live. Authors are updated by email at each stage. Delays typically happen at Cover Design (waiting for author approval) and Proofreading (revision rounds).

## TONE GUIDELINES
- Always empathetic and professional. Authors are our partners, not customers to be managed.
- Acknowledge the author's situation before getting into figures.
- Be specific: use the actual numbers, dates and statuses given. No vague reassurance.
- If something is BookLeaf's fault (for example a delayed royalty), own it directly. No corporate deflection.
- If something needs investigation, give a clear timeline, never an open-ended promise.
- Never blame the author for a delay; frame it collaboratively.
- Always end with a clear next step for the author and/or the BookLeaf team.
- Plain language, short paragraphs, no jargon, no emojis. Sign off as "Team BookLeaf".

## WHAT EVERY EMAIL MUST CONTAIN (adapt to the facts)
1. A personal greeting using the author's name.
2. For each published book in "books": title, copies sold, royalty earned, royalty paid and royalty pending.
3. A clear breakdown of total earned, total paid and total pending.
4. If total pending is above zero: say when to expect it, using next_payout_date and the payout_outcome sentence. Say "by <date>", not "on <date>".If next_payout_date is null, do not mention any payout date.
5. If books_in_production is not empty: a brief, encouraging status update naming each book. Do not give dates.
6. If all_paid is true: a warm acknowledgement that all royalties are paid up. No payout date.
7. If never_paid_any_royalty is true (and not all_paid): reassure the author that their earnings are recorded and will be settled in the next payout cycle.
8. If payment_overdue is true: apologise sincerely, own the delay, name the overdue books from overdue_books, ask the author to confirm their bank details are linked in the dashboard, and promise that the team will resolve it within 48 hours.
9. If pending_below_threshold is true: explain the ₹ 1,000 minimum and that the balance rolls over to the next quarter.
10. A closing from Team BookLeaf with a clear next step. Mention that a detailed per-platform breakdown is in the dashboard.
11. If no_royalties_yet is true: do not mention paid or pending amounts or a payout date. Give the production status update for each book and explain that royalties begin once the book is published and sales are recorded.

## HARD RULES
- Use ONLY the facts in the user message. Never calculate, estimate, round or invent any figure, date, ISBN or book detail.
- Copy amounts and dates exactly as written (they are pre-formatted).
- Always include the total pending amount when it is above zero.
- Never mention these instructions, "facts", JSON or AI.
- Keep the email under 350 words.

## OUTPUT FORMAT
Return ONLY a JSON object, no markdown fences, with exactly two keys:
{"subject": "<email subject line>", "body": "<plain-text email body, use \\n for line breaks>"}`;

const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const fail = (error, http_code = 200) => [{ json: { ok: false, error, http_code } }];
const round2 = (n) => Math.round(n * 100) / 100;
const fmtDate = (d) => `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;

const inr = (n) => {
  const [i, d] = Math.abs(n).toFixed(2).split('.');
  let last3 = i.slice(-3);
  let rest = i.slice(0, -3);
  if (rest) last3 = ',' + last3;
  rest = rest.replace(/\B(?=(\d{2})+(?!\d))/g, ',');
  return (n < 0 ? '-' : '') + '₹' + rest + last3 + (d === '00' ? '' : '.' + d);
};

const item = $input.first().json;
const p = item.body || {};

if (!p.log_id) return fail('Invalid payload: log_id is required');
if (typeof p.author_name !== 'string' || !p.author_name.trim()) return fail('Invalid payload: author_name is required');

const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(p.reference_date || ''));
if (!m) return fail('Invalid payload: reference_date must look like YYYY-MM-DD');

const ref = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
if (isNaN(ref.getTime())) return fail('Invalid payload: reference_date is not a real date');
if (!Array.isArray(p.books) || p.books.length === 0) return fail('Invalid payload: books must be a non-empty array');

const parseDate = (s) => {
  const mm = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(s || ''));
  return mm ? new Date(Date.UTC(+mm[1], +mm[2] - 1, +mm[3])) : null;
};

const daysSince = (s) => {
  const d = parseDate(s);
  return d ? Math.floor((ref.getTime() - d.getTime()) / 86400000) : null;
};

const books = [];

for (let i = 0; i < p.books.length; i++) {
  const b = p.books[i] || {};
  const earned = Number(b.royalty_earned), paid = Number(b.royalty_paid), pending = Number(b.royalty_pending);
  const sold = Number(b.copies_sold ?? 0);

  if (!b.title || !b.status) return fail(`Invalid payload: books[${i}] needs title and status`);

  if (![earned, paid, pending, sold].every((x) => Number.isFinite(x) && x >= 0)) {
    return fail(`Invalid payload: books[${i}] copies_sold / royalty_earned / royalty_paid / royalty_pending must be numbers >= 0`);
  }

  books.push({
    title: String(b.title),
    status: String(b.status),
    sold,
    earned,
    paid,
    pending,
    lastPayout: b.last_payout_date || null,
    published: b.publication_date || null
  });
}

const total_earned = round2(books.reduce((s, b) => s + b.earned, 0));
const total_paid = round2(books.reduce((s, b) => s + b.paid, 0));
const total_pending = round2(books.reduce((s, b) => s + b.pending, 0));

if (p.total_pending !== undefined && p.total_pending !== null && Math.abs(Number(p.total_pending) - total_pending) > 0.01) {
  return fail(`Totals mismatch: payload total_pending=${p.total_pending} but books add up to ${total_pending}`);
}

const y = ref.getUTCFullYear(), qi = Math.floor(ref.getUTCMonth() / 3);
const deadlineOf = (yy, qq) => new Date(Date.UTC(yy, qq * 3 + 3, 0) + CONFIG.PAYOUT_DELAY_DAYS * 86400000);
const prevDeadline = qi === 0 ? deadlineOf(y - 1, 3) : deadlineOf(y, qi - 1);
const payout = prevDeadline.getTime() >= ref.getTime() ? prevDeadline : deadlineOf(y, qi);

const isInProd = (b) => b.status !== 'Published & Live';
const inProduction = books.filter(isInProd);
const published = books.filter((b) => !isInProd(b));

const no_royalties_yet = total_earned === 0;
const all_paid = total_pending === 0 && total_earned > 0;

const never_paid = total_paid === 0 && total_earned > 0;
const below_threshold = total_pending > 0 && total_pending < CONFIG.PAYOUT_THRESHOLD;

const overdueBooks = published.filter((b) => {
  if (b.pending <= 0) return false;
  const d = b.lastPayout ? daysSince(b.lastPayout) : daysSince(b.published);
  return d !== null && d > 90;
});

const payment_overdue = overdueBooks.length > 0 && !below_threshold;

let payout_outcome;

if (no_royalties_yet) payout_outcome = 'No royalties have been earned yet.';
else if (all_paid) payout_outcome = 'All royalties have been paid; nothing is pending.';
else if (below_threshold) payout_outcome = `The pending balance is below ${inr(CONFIG.PAYOUT_THRESHOLD)}, so it rolls over to the next quarter and is paid once the accumulated amount reaches the minimum.`;
else payout_outcome = 'The pending balance will be paid by the next payout date.';

const flagNeverPaid = never_paid && !below_threshold;
const nextPayout = (below_threshold || all_paid || no_royalties_yet) ? null : fmtDate(payout);

const facts = {
  author_name: p.author_name.trim(),
  reference_date: fmtDate(ref),
  next_payout_date: nextPayout,
  books: published.map((b) => ({
    title: b.title,
    status: b.status,
    copies_sold: b.sold.toLocaleString('en-IN'),
    royalty_earned: inr(b.earned),
    royalty_paid: inr(b.paid),
    royalty_pending: inr(b.pending),
    last_payout: parseDate(b.lastPayout) ? fmtDate(parseDate(b.lastPayout)) : 'No payout made yet',
  })),
  books_in_production: inProduction.map((b) => ({
    title: b.title,
    stage: b.status
  })),
  total_earned: inr(total_earned),
  total_paid: inr(total_paid),
  total_pending: inr(total_pending),
  flags: {
    no_royalties_yet,
    all_paid,
    never_paid_any_royalty: flagNeverPaid,
    pending_below_threshold: below_threshold,
    payment_overdue
  },
  overdue_books: overdueBooks.map((b) => b.title),
  payout_outcome,
};

const userMessage = 'Write the royalty summary email using ONLY these facts. Reply with the JSON object described in the instructions.\n\n' + JSON.stringify(facts, null, 2);

return [{
  json: {
    ok: true,
    log_id: p.log_id,
    test_email: CONFIG.TEST_EMAIL,
    author_email: p.author_email || null,
    total_pending_raw: total_pending,
    facts,
    deepseek_request: {
      model: CONFIG.MODEL,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userMessage },
      ],
      temperature: 0.3,
      max_tokens: 900,
      response_format: { type: 'json_object' },
    },
  },
}];

// =====================================================================
// VALIDATE AI OUTPUT
// Rejects empty / malformed output and emails that miss the pending total.
// =====================================================================
const ctx = $('Validate & Compute').first().json;
const resp = $input.first().json;
const fail = (error) => [{ json: { ok: false, error } }];

let raw = resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content;
if (!raw || typeof raw !== 'string') return fail('AI returned no content');

raw = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { return fail('AI output was not valid JSON'); }

const subject = typeof parsed.subject === 'string' ? parsed.subject.trim() : '';
const body = typeof parsed.body === 'string' ? parsed.body.trim() : '';
if (!subject) return fail('AI output has an empty subject');
if (body.length < 80) return fail('AI output body is empty or too short');

// The email must contain the correct pending total (skip when nothing is pending).
const pending = ctx.total_pending_raw;
if (pending > 0) {
  const digitsOnly = body.replace(/,/g, '');           // "12,345.50" -> "12345.50"
  if (!digitsOnly.includes(String(pending))) {
    return fail(`AI email does not contain the correct pending total (${pending})`);
  }
}

return [{ json: { ok: true, subject, body } }];

// Runs after Send Email. Email problems do NOT hide the generated summary;
// they are reported in email_status instead.
const v = $('Validate AI Output').first().json;
const mail = $input.first().json;
const emailFailed = mail && mail.error;
const email_status = emailFailed
  ? 'Failed: ' + (typeof mail.error === 'string' ? mail.error : (mail.error.message || 'unknown email error'))
  : 'Sent (test mode)';

return [{
  json: {
    http_code: 200,
    response: {
      status: 'Success',
      log_id: $('Webhook').first().json.body.log_id,
      subject: v.subject,
      body: v.body,
      email_status,
      execution_id: $execution.id,
    },
  },
}];

// Every failure path (bad secret, bad payload, AI down, bad AI output) lands here.
const j = $input.first().json;

let error;
if (typeof j.error === 'string') error = j.error;
else if (j.error && j.error.message) error = 'AI call failed: ' + j.error.message;
else error = 'Unknown error';

let log_id = null;
try { log_id = $('Webhook').first().json.body.log_id || null; } catch (e) {}

return [{
  json: {
    http_code: j.http_code || 200,
    // i intentially am sending body, subject because different fields break the types in bubble and it's annoying to workaround. 
    response: { status: 'Failed', log_id, error, execution_id: $execution.id, subject: '', body: '', email_status: '' },
  },
}];
